CREATE TABLE public.pm_app_roles(user_id uuid PRIMARY KEY REFERENCES public.profiles(id),role text NOT NULL CHECK(role IN ('manager','member')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.pm_app_roles TO authenticated; GRANT ALL ON public.pm_app_roles TO service_role; ALTER TABLE public.pm_app_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY pm_roles_read ON public.pm_app_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_erp_admin(auth.uid()));
CREATE POLICY pm_roles_admin ON public.pm_app_roles FOR ALL TO authenticated USING(public.is_erp_admin(auth.uid())) WITH CHECK(public.is_erp_admin(auth.uid()));
CREATE TABLE public.pm_projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(trim(name))>0),category text NOT NULL DEFAULT 'Interno',scope text NOT NULL DEFAULT '',erp_project_id uuid REFERENCES public.projects(id),manager_id uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'planejamento' CHECK(status IN ('planejamento','em_andamento','pausado','concluido','cancelado')),start_date date NOT NULL,calendar_mode text NOT NULL DEFAULT 'business' CHECK(calendar_mode IN ('business','calendar')),hours_per_day numeric NOT NULL DEFAULT 8 CHECK(hours_per_day>0 AND hours_per_day<=24),holidays date[] NOT NULL DEFAULT '{}',budget numeric NOT NULL DEFAULT 0 CHECK(budget>=0),created_by uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.pm_projects TO authenticated; GRANT ALL ON public.pm_projects TO service_role; ALTER TABLE public.pm_projects ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.pm_members(project_id uuid NOT NULL REFERENCES public.pm_projects(id),user_id uuid NOT NULL REFERENCES public.profiles(id),role text NOT NULL DEFAULT 'member' CHECK(role IN ('manager','member')),PRIMARY KEY(project_id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.pm_members TO authenticated; GRANT ALL ON public.pm_members TO service_role; ALTER TABLE public.pm_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.pm_can_create() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.has_app_access(auth.uid(),'projects') AND (public.is_erp_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.pm_app_roles WHERE user_id=auth.uid() AND role='manager')) $$;
CREATE FUNCTION public.pm_can_manage(_project uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.has_app_access(auth.uid(),'projects') AND (public.is_erp_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.pm_projects WHERE id=_project AND manager_id=auth.uid()) OR EXISTS(SELECT 1 FROM public.pm_members WHERE project_id=_project AND user_id=auth.uid() AND role='manager')) $$;
CREATE FUNCTION public.pm_can_edit(_project uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.has_app_access(auth.uid(),'projects') AND (public.pm_can_manage(_project) OR EXISTS(SELECT 1 FROM public.pm_members WHERE project_id=_project AND user_id=auth.uid())) $$;
REVOKE ALL ON FUNCTION public.pm_can_create(),public.pm_can_manage(uuid),public.pm_can_edit(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pm_can_create(),public.pm_can_manage(uuid),public.pm_can_edit(uuid) TO authenticated,service_role;
CREATE POLICY pm_projects_read ON public.pm_projects FOR SELECT TO authenticated USING(public.pm_can_edit(id));
CREATE POLICY pm_projects_create ON public.pm_projects FOR INSERT TO authenticated WITH CHECK(public.pm_can_create() AND manager_id=auth.uid() AND created_by=auth.uid());
CREATE POLICY pm_projects_update ON public.pm_projects FOR UPDATE TO authenticated USING(public.pm_can_edit(id)) WITH CHECK(public.pm_can_edit(id));
CREATE POLICY pm_members_read ON public.pm_members FOR SELECT TO authenticated USING(public.pm_can_edit(project_id));
CREATE POLICY pm_members_manage ON public.pm_members FOR ALL TO authenticated USING(public.pm_can_manage(project_id)) WITH CHECK(public.pm_can_manage(project_id) AND private.has_app_access(user_id,'projects'));
CREATE TABLE public.pm_phases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.pm_projects(id),name text NOT NULL CHECK(length(trim(name))>0),deliverables text NOT NULL DEFAULT '',position integer NOT NULL DEFAULT 0,accepted_at timestamptz,accepted_by uuid REFERENCES public.profiles(id));
CREATE TABLE public.pm_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.pm_projects(id),phase_id uuid REFERENCES public.pm_phases(id),name text NOT NULL CHECK(length(trim(name))>0),duration integer NOT NULL DEFAULT 1 CHECK(duration>=0 AND duration<=10000),start_date date NOT NULL,milestone boolean NOT NULL DEFAULT false,progress numeric NOT NULL DEFAULT 0 CHECK(progress>=0 AND progress<=100),actual_start date,actual_end date,responsible_id uuid REFERENCES public.profiles(id),position integer NOT NULL DEFAULT 0,notes text NOT NULL DEFAULT '',CHECK(NOT milestone OR duration=0),CHECK(actual_end IS NULL OR actual_start IS NOT NULL AND actual_end>=actual_start));
CREATE TABLE public.pm_dependencies(project_id uuid NOT NULL REFERENCES public.pm_projects(id),predecessor_id uuid NOT NULL REFERENCES public.pm_tasks(id),successor_id uuid NOT NULL REFERENCES public.pm_tasks(id),lag integer NOT NULL DEFAULT 0 CHECK(lag>=0),PRIMARY KEY(predecessor_id,successor_id),CHECK(predecessor_id<>successor_id));
CREATE TABLE public.pm_resources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.pm_projects(id),name text NOT NULL CHECK(length(trim(name))>0),kind text NOT NULL DEFAULT 'person' CHECK(kind IN ('person','material','service')),user_id uuid REFERENCES public.profiles(id),unit text NOT NULL DEFAULT 'h',rate numeric NOT NULL DEFAULT 0 CHECK(rate>=0),capacity_per_day numeric NOT NULL DEFAULT 8 CHECK(capacity_per_day>0));
CREATE TABLE public.pm_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.pm_projects(id),task_id uuid NOT NULL REFERENCES public.pm_tasks(id),resource_id uuid NOT NULL REFERENCES public.pm_resources(id),planned_quantity numeric NOT NULL DEFAULT 0 CHECK(planned_quantity>=0),actual_quantity numeric NOT NULL DEFAULT 0 CHECK(actual_quantity>=0),unit_rate numeric NOT NULL DEFAULT 0 CHECK(unit_rate>=0),UNIQUE(task_id,resource_id));
CREATE TABLE public.pm_baselines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.pm_projects(id),name text NOT NULL, snapshot jsonb NOT NULL,created_by uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.pm_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.pm_projects(id),entity text NOT NULL,entity_id text NOT NULL,action text NOT NULL,old_data jsonb,new_data jsonb,actor_id uuid REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.pm_phases,public.pm_tasks,public.pm_dependencies,public.pm_resources,public.pm_allocations TO authenticated; GRANT ALL ON public.pm_phases,public.pm_tasks,public.pm_dependencies,public.pm_resources,public.pm_allocations,public.pm_baselines,public.pm_logs TO service_role; GRANT SELECT,INSERT ON public.pm_baselines TO authenticated; GRANT SELECT ON public.pm_logs TO authenticated;
ALTER TABLE public.pm_phases ENABLE ROW LEVEL SECURITY; ALTER TABLE public.pm_tasks ENABLE ROW LEVEL SECURITY; ALTER TABLE public.pm_dependencies ENABLE ROW LEVEL SECURITY; ALTER TABLE public.pm_resources ENABLE ROW LEVEL SECURITY; ALTER TABLE public.pm_allocations ENABLE ROW LEVEL SECURITY; ALTER TABLE public.pm_baselines ENABLE ROW LEVEL SECURITY; ALTER TABLE public.pm_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY pm_phases_access ON public.pm_phases FOR ALL TO authenticated USING(public.pm_can_edit(project_id)) WITH CHECK(public.pm_can_edit(project_id));
CREATE POLICY pm_tasks_access ON public.pm_tasks FOR ALL TO authenticated USING(public.pm_can_edit(project_id)) WITH CHECK(public.pm_can_edit(project_id));
CREATE POLICY pm_dependencies_access ON public.pm_dependencies FOR ALL TO authenticated USING(public.pm_can_edit(project_id)) WITH CHECK(public.pm_can_edit(project_id));
CREATE POLICY pm_resources_access ON public.pm_resources FOR ALL TO authenticated USING(public.pm_can_edit(project_id)) WITH CHECK(public.pm_can_edit(project_id));
CREATE POLICY pm_allocations_access ON public.pm_allocations FOR ALL TO authenticated USING(public.pm_can_edit(project_id)) WITH CHECK(public.pm_can_edit(project_id));
CREATE POLICY pm_baselines_read ON public.pm_baselines FOR SELECT TO authenticated USING(public.pm_can_edit(project_id));
CREATE POLICY pm_baselines_create ON public.pm_baselines FOR INSERT TO authenticated WITH CHECK(public.pm_can_manage(project_id) AND created_by=auth.uid());
CREATE POLICY pm_logs_read ON public.pm_logs FOR SELECT TO authenticated USING(public.pm_can_edit(project_id));
CREATE FUNCTION public.pm_guard_row() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF TG_TABLE_NAME='pm_projects' THEN IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.manager_id IS DISTINCT FROM OLD.manager_id) THEN RAISE EXCEPTION 'Identidade e gestor do projeto são preservados'; END IF; NEW.updated_at:=now(); RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.project_id IS DISTINCT FROM OLD.project_id THEN RAISE EXCEPTION 'Não é permitido mover registros entre projetos'; END IF;
 IF EXISTS(SELECT 1 FROM public.pm_projects WHERE id=NEW.project_id AND status IN ('concluido','cancelado')) THEN RAISE EXCEPTION 'Projeto encerrado não pode ser alterado'; END IF;
 IF TG_TABLE_NAME='pm_tasks' THEN IF NEW.phase_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.pm_phases WHERE id=NEW.phase_id AND project_id=NEW.project_id) THEN RAISE EXCEPTION 'Fase de outro projeto'; END IF; IF NEW.responsible_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.pm_projects WHERE id=NEW.project_id AND manager_id=NEW.responsible_id) AND NOT EXISTS(SELECT 1 FROM public.pm_members WHERE project_id=NEW.project_id AND user_id=NEW.responsible_id) THEN RAISE EXCEPTION 'Responsável não pertence à equipe'; END IF; END IF;
 IF TG_TABLE_NAME='pm_allocations' AND (NOT EXISTS(SELECT 1 FROM public.pm_tasks WHERE id=NEW.task_id AND project_id=NEW.project_id) OR NOT EXISTS(SELECT 1 FROM public.pm_resources WHERE id=NEW.resource_id AND project_id=NEW.project_id)) THEN RAISE EXCEPTION 'Alocação de outro projeto'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER pm_project_guard BEFORE INSERT OR UPDATE ON public.pm_projects FOR EACH ROW EXECUTE FUNCTION public.pm_guard_row();
CREATE TRIGGER pm_phase_guard BEFORE INSERT OR UPDATE ON public.pm_phases FOR EACH ROW EXECUTE FUNCTION public.pm_guard_row();
CREATE TRIGGER pm_task_guard BEFORE INSERT OR UPDATE ON public.pm_tasks FOR EACH ROW EXECUTE FUNCTION public.pm_guard_row();
CREATE TRIGGER pm_resource_guard BEFORE INSERT OR UPDATE ON public.pm_resources FOR EACH ROW EXECUTE FUNCTION public.pm_guard_row();
CREATE TRIGGER pm_allocation_guard BEFORE INSERT OR UPDATE ON public.pm_allocations FOR EACH ROW EXECUTE FUNCTION public.pm_guard_row();
CREATE FUNCTION public.pm_dependency_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(NEW.project_id::text,0)); IF NOT EXISTS(SELECT 1 FROM public.pm_tasks WHERE id=NEW.predecessor_id AND project_id=NEW.project_id) OR NOT EXISTS(SELECT 1 FROM public.pm_tasks WHERE id=NEW.successor_id AND project_id=NEW.project_id) THEN RAISE EXCEPTION 'Dependência de outro projeto'; END IF; IF EXISTS(WITH RECURSIVE reach(id) AS (SELECT successor_id FROM public.pm_dependencies WHERE predecessor_id=NEW.successor_id UNION SELECT d.successor_id FROM public.pm_dependencies d JOIN reach r ON d.predecessor_id=r.id) SELECT 1 FROM reach WHERE id=NEW.predecessor_id) THEN RAISE EXCEPTION 'Dependência circular'; END IF; RETURN NEW; END $$;
CREATE TRIGGER pm_dependency_guard BEFORE INSERT OR UPDATE ON public.pm_dependencies FOR EACH ROW EXECUTE FUNCTION public.pm_dependency_guard();
CREATE FUNCTION public.pm_audit_row() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p uuid; e text; BEGIN IF TG_TABLE_NAME='pm_projects' THEN p:=COALESCE(NEW.id,OLD.id); ELSE p:=COALESCE(NEW.project_id,OLD.project_id); END IF; e:=COALESCE(to_jsonb(NEW)->>'id',to_jsonb(OLD)->>'id',to_jsonb(NEW)->>'user_id',to_jsonb(OLD)->>'user_id',to_jsonb(NEW)->>'successor_id',to_jsonb(OLD)->>'successor_id'); INSERT INTO public.pm_logs(project_id,entity,entity_id,action,old_data,new_data,actor_id) VALUES(p,TG_TABLE_NAME,COALESCE(e,p::text),TG_OP,CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD) END,CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW) END,auth.uid()); RETURN COALESCE(NEW,OLD); END $$;
REVOKE ALL ON FUNCTION public.pm_audit_row() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER pm_project_audit AFTER INSERT OR UPDATE ON public.pm_projects FOR EACH ROW EXECUTE FUNCTION public.pm_audit_row();
CREATE TRIGGER pm_task_audit AFTER INSERT OR UPDATE OR DELETE ON public.pm_tasks FOR EACH ROW EXECUTE FUNCTION public.pm_audit_row();
CREATE TRIGGER pm_phase_audit AFTER INSERT OR UPDATE OR DELETE ON public.pm_phases FOR EACH ROW EXECUTE FUNCTION public.pm_audit_row();
CREATE TRIGGER pm_members_audit AFTER INSERT OR UPDATE OR DELETE ON public.pm_members FOR EACH ROW EXECUTE FUNCTION public.pm_audit_row();
CREATE TRIGGER pm_resource_audit AFTER INSERT OR UPDATE OR DELETE ON public.pm_resources FOR EACH ROW EXECUTE FUNCTION public.pm_audit_row();
CREATE TRIGGER pm_allocation_audit AFTER INSERT OR UPDATE OR DELETE ON public.pm_allocations FOR EACH ROW EXECUTE FUNCTION public.pm_audit_row();
CREATE TRIGGER pm_dependency_audit AFTER INSERT OR UPDATE OR DELETE ON public.pm_dependencies FOR EACH ROW EXECUTE FUNCTION public.pm_audit_row();
CREATE TRIGGER pm_baseline_audit AFTER INSERT ON public.pm_baselines FOR EACH ROW EXECUTE FUNCTION public.pm_audit_row();
CREATE FUNCTION public.pm_team_candidates() RETURNS TABLE(id uuid,full_name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.full_name FROM public.profiles p WHERE private.has_app_access(auth.uid(),'projects') AND private.has_app_access(p.id,'projects') AND p.is_active AND p.deleted_at IS NULL ORDER BY p.full_name $$;
REVOKE ALL ON FUNCTION public.pm_team_candidates() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pm_team_candidates() TO authenticated,service_role;